(function(){'use strict';function boot(){var wrap=document.querySelector('.hq-3d-stage');if(!wrap||wrap.dataset.v16Live==='1')return;wrap.dataset.v16Live='1';var old=wrap.querySelector('.office-scene');if(old)old.remove();var frame=document.createElement('iframe');frame.src='hq-office-live.html?v=16-main';frame.className='live-office-frame';frame.title='NAWAF HQ live office';frame.style.position='absolute';frame.style.inset='0';frame.style.width='100%';frame.style.height='100%';frame.style.border='0';frame.style.zIndex='2';frame.style.background='#101720';wrap.prepend(frame);var nodes=wrap.querySelectorAll('.room-nav,.scene-brand,.scene-status');nodes.forEach(function(n){n.style.display='none'});wrap.style.minHeight='620px';}window.NawafHQ3D=boot;function start(){setTimeout(boot,120)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();window.addEventListener('nawaf:state-updated',function(){var w=document.querySelector('.hq-3d-stage');if(w){w.dataset.v16Live='';var f=w.querySelector('.live-office-frame');if(f)f.remove();setTimeout(boot,120)}});})();